out={}
for k,s in src.items():
    P,N,Q,A,X=T[k]
    assert len(P)==len(s['phrases']) and len(N)==len(s['nouns']), k
    R=P+X; assert len(R)==len(s['recall']), (k,len(R),len(s['recall']))
    # noun recall items must match noun translations
    for i,r in enumerate(s['recall'][3:]):
        if r in s['nouns']: assert X[i]==N[s['nouns'].index(r)], k
    out[k]={"phrases":P,"nouns":N,"question":Q,"answer":A,"captions":{},"recall":R}
assert set(T)==set(src)
json.dump(out,open(f'{H}/tr/b001/es/hu.json','w'),ensure_ascii=False,indent=1)
